{"op":"add","path":"/root","value":"main"}
{"op":"add","path":"/elements/main","value":{"type":"Stack","props":{"direction":"vertical","gap":"lg"},"children":["page-header","billing-row","plans-grid","confirm-alert","footer-note"]}}
{"op":"add","path":"/elements/page-header","value":{"type":"Stack","props":{"direction":"vertical","gap":"sm","align":"center"},"children":["page-title","page-intro"]}}
{"op":"add","path":"/elements/page-title","value":{"type":"Heading","props":{"text":"Simple, transparent pricing","level":"h1"},"children":[]}}
{"op":"add","path":"/elements/page-intro","value":{"type":"Text","props":{"text":"Three plans, no hidden fees. Start free and upgrade when your team needs more room, more storage or more control.","variant":"lead"},"children":[]}}
{"op":"add","path":"/elements/billing-row","value":{"type":"Stack","props":{"direction":"horizontal","gap":"md","align":"center"},"children":["billing-label","billing-switch"]}}
{"op":"add","path":"/elements/billing-label","value":{"type":"Text","props":{"text":"Billing period","variant":"small"},"children":[]}}
{"op":"add","path":"/elements/billing-switch","value":{"type":"Switch","props":{"label":"Bill annually","description":"Save 20% versus monthly billing","checked":{"$bindState":"/annual"}},"children":[]}}
{"op":"add","path":"/elements/plans-grid","value":{"type":"Grid","props":{"columns":"3","gap":"md"},"repeat":{"statePath":"/plans","key":"id"},"children":["plan-card"]}}
{"op":"add","path":"/elements/plan-card","value":{"type":"Card","props":{"title":{"$template":"${name}"},"description":{"$template":"${tagline}"}},"children":["plan-body"]}}
{"op":"add","path":"/elements/plan-body","value":{"type":"Stack","props":{"direction":"vertical","gap":"md","align":"start"},"children":["plan-badge","price-monthly","price-annual","plan-separator","plan-features","plan-cta","plan-note"]}}
{"op":"add","path":"/elements/plan-badge","value":{"type":"Badge","props":{"text":"Most popular","variant":"default"},"visible":{"$item":"popular"},"children":[]}}
{"op":"add","path":"/elements/price-monthly","value":{"type":"Heading","props":{"text":{"$template":"${monthlyPrice}"},"level":"h2"},"visible":{"$state":"/annual","not":true},"children":[]}}
{"op":"add","path":"/elements/price-annual","value":{"type":"Heading","props":{"text":{"$template":"${annualPrice}"},"level":"h2"},"visible":{"$state":"/annual"},"children":[]}}
{"op":"add","path":"/elements/plan-separator","value":{"type":"Separator","props":{},"children":[]}}
{"op":"add","path":"/elements/plan-features","value":{"type":"List","props":{"items":{"$item":"features"},"ordered":false},"children":[]}}
{"op":"add","path":"/elements/plan-cta","value":{"type":"Button","props":{"label":{"$template":"${cta}"},"variant":{"$cond":{"$item":"popular"},"$then":"default","$else":"outline"},"size":"default"},"on":{"press":{"action":"setState","params":{"statePath":"/selectedPlan","value":{"$template":"${name}"}}}},"children":[]}}
{"op":"add","path":"/elements/plan-note","value":{"type":"Text","props":{"text":{"$template":"${note}"},"variant":"small"},"children":[]}}
{"op":"add","path":"/elements/confirm-alert","value":{"type":"Alert","props":{"title":"Plan selected","description":{"$template":"You picked ${/selectedPlan}. Next step: create your workspace and invite your team."},"variant":"default"},"visible":{"$state":"/selectedPlan"},"children":[]}}
{"op":"add","path":"/elements/footer-note","value":{"type":"Text","props":{"text":"All prices in USD. Monthly plans can be cancelled anytime; annual plans are refunded pro-rata.","variant":"muted"},"children":[]}}
{"op":"add","path":"/state/annual","value":false}
{"op":"add","path":"/state/selectedPlan","value":""}
{"op":"add","path":"/state/plans","value":[]}
